(window.FREALLY_I18N = window.FREALLY_I18N || {})["ar"] = {"hero.headline":"<span class=\"hl-muted\">ضعه على الزجاج. اضغط START.</span> <span class=\"cycle\" data-cycle=\"hero.cycle\">اسحب النسخة.</span>","hero.cycle":"اسحب النسخة.|اسحب ملف MIDI.|اسحب الصوت.","hero.sub":"صوت في الداخل، MIDI في الخارج. MIDI في الداخل، صوت في الخارج. مجاني، بلا اتصال، وخالٍ من الذكاء الاصطناعي بنسبة 100%.","hero.chipStandalone":"مستقل","what.title":"ما هو","what.p1":"تحويل لوب إلى MIDI، أو ملف MIDI إلى صوت، يعني عادةً سلسلة من الأدوات، وتصديرًا، وإعادة استيراد، والكثير من التخمين حول ما نتج عن ذلك.","what.p2":"Flipcopy آلة نسخ. ضع ملف صوت أو ملف MIDI على زجاجها فتطبع الأصل — الموجة الصوتية الحقيقية، أو كل نغمة، مع بياناتها. اضغط على START الأخضر فتطبع النسخة بالشكل الآخر: صوت في الداخل، MIDI في الخارج؛ MIDI في الداخل، صوت في الخارج.","what.p3":"تخرج النسخة كصفحة مطبوعة بإطار أخضر فسفوري حول مقطعها. أمسك الإطار واسحبه إلى مسار في الـ DAW الخاص بك. كل نسخة هي ملف حقيقي يبقى في مكانه، لذا لا يفقده مشروعك أبدًا.","see.title":"شاهدها وهي تنسخ","see.intro":"آلة النسخ، مُصوَّرة في Blender: يصل الأصل إلى الزجاج، يُغلق الغطاء، يمسح المصباح، وتنزلق النسخة إلى الخارج على الدرج.","see.start":"اضغط START لتشاهدها وهي تنسخ","see.audioToMidi":"صوت في الداخل، MIDI في الخارج: صفحة لكل طبقة — اللحن والأكوردات وخط الباص واللحن المضاد.","see.midiToAudio":"MIDI في الداخل، صوت في الخارج.","features.title":"ما الذي يحتويه","features.copier.title":"آلة النسخ","features.copier.body":"آلة نسخ واقعية الصورة، مُصوَّرة في Blender. ضع مقطعًا على الزجاج فتطبع الشيء الحقيقي: كل نغمة، أو الموجة الصوتية الحقيقية، مع سرعتها وطولها ومستوياتها.","features.start.title":"زر START الأخضر","features.start.body":"إفلات مقطع لا يفعل سوى وضعه على الزجاج. لا يُنسخ شيء حتى تضغط START، لذا لا يحدث شيء لم تطلبه.","features.audioToMidi.title":"صوت ← MIDI","features.audioToMidi.body":"الطبول والباص واللحن واللحن المضاد والأكوردات الموجودة في اللوب، لكل منها صفحة، تُطبع متتالية من مسح واحد، فتسحبها إلى برنامج DAW كمسارات منفصلة.","features.midiToAudio.title":"MIDI ← صوت","features.midiToAudio.body":"ملف MIDI يُعزف عبر آلة حقيقية، والطبول عبر آلة إيقاع، مطبوعة كملف صوتي يمكنك سحبه.","features.drag.title":"اسحب النسخة","features.drag.body":"كل صفحة تحمل إطارًا أخضر فسفوريًا حول مقطعها. أمسكه وأفلته على مسار. الملف حقيقي، ولا يستبدله Flipcopy أو يحذفه أبدًا.","features.browser.title":"المتصفح","features.browser.body":"متصفح ملفات مزوَّد بمشغّل معاينة، من Freally Oscillate. يعرض موجة صوتية للصوت والنغمات لملفات MIDI، ويشغّل MIDI عبر الآلة التي تستخدمها النسخة.","features.daw.title":"في أي DAW","features.daw.body":"CLAP وVST3 وAU، إضافةً إلى تطبيق مستقل للعمل بلا DAW ولبرنامج Pro Tools. Windows وmacOS وLinux.","features.free.title":"مجاني، بلا اتصال، بلا ذكاء اصطناعي","features.free.body":"لا مستويات، لا حساب، لا قياس عن بُعد، لا شبكة، لا نموذج. معالجة إشارة كلاسيكية، تفرضها بوابة بناء لا مجرد وعد بها.","docs.language.title":"اللغات","docs.language.p1":"يتحدث Flipcopy ثماني عشرة لغة. يبدأ بلغة نظامك؛ ولاختيار لغة أخرى، افتح الإعدادات من أيقونة الترس أعلى المتصفح واختر واحدة. ينطبق الاختيار على كل نسخة من Flipcopy على الجهاز.","ladder.title":"الطريق إلى 1.0","ladder.intro":"سطر واحد لكل إصدار. هذا هو السلّم نفسه الذي تتبعه الخطة الخاصة — إن تحرّك أحدهما تحرّك الآخر، وتقارنهما بوابة بناء.","ladder.rung.v0.1.0":"الأساس: يُحمَّل المكوّن الإضافي بصيغ CLAP وVST3 وAU وكتطبيق مستقل، ويمرّر صوتك دون أن يمسّه، ويطلب منك قبول ترخيصه، وتعمل كل بوابات الجودة.","ladder.rung.v0.2.0":"آلة النسخ والنسخة الأولى: الآلة داخل النافذة، وزر START الأخضر، وملف MIDI يُنسخ إلى صوت تسحبه مباشرةً إلى الـ DAW الخاص بك.","ladder.rung.v0.3.0":"من الصوت إلى MIDI: ضع لوبًا على الزجاج، واضغط START، واسحب منه الطبول والباص واللحن والأكوردات بصيغة MIDI.","ladder.rung.v0.4.0":"متصفح الملفات ومشغّل المعاينة: اعثر على عيّنة أو مقطع MIDI، واستمع إليه وشاهده، ثم اسحبه إلى الزجاج. كل ما هو أساسي موجود هنا.","ladder.rung.v0.5.0":"الشاشة اللمسية: إعدادات النسخ، وآلات موسيقية لنسخك، وصيغ الملفات، وسجلّ كل نسخة صنعتها.","ladder.rung.v0.5.5":"الاستوديو: افتح أي نسخة في لفافة بيانو، وغيّر نغماتها، واستمع إليها بأي آلة موسيقية، واطبع تعديلك كنسخة جديدة.","ladder.rung.v0.5.7":"الخلاط وآلاتك الموسيقية الخاصة: مقابض واقعية لتشكيل كل جزء، وأطقم الطبول والعينات الخاصة بك، والمفضلة، ومكتبة آلات واحدة تتشاركها كل تطبيقات Freally.","ladder.rung.v0.5.9":"السمات والوضع الفاتح: خمس سمات لافتة للأنظار، مرسومة بالشيفرة ومتطابقة في كل تطبيقات Freally، كلٌّ منها بنسختين فاتحة وداكنة، إلى جانب وضع فاتح جديد.","ladder.rung.v0.6.0":"في كل DAW: يُحفظ مع مشروعك، وعدة نسخ في آنٍ واحد، ومسح مباشر من مسار، واختبار في كل DAW على حدة.","ladder.rung.v0.7.0":"التطبيق المستقل بكامل قدراته، وmacOS وLinux، وفيديو لآلة النسخ وهي تعمل.","ladder.rung.v0.8.0":"الدقة والواقعية والسرعة: تدوين نوتة أفضل، وآلة أكثر إقناعًا، وفرض صارم لكل ميزانيات الأداء.","ladder.rung.v1.0.0-beta":"التحصين: مثبّتات لثلاثة أنظمة، وفحص التحديثات الاختياري، والدليل المصوَّر الكامل. ولا تنزيلات على هذا الموقع حتى الآن.","ladder.rung.v1.0.0-rc":"الإصدار المرشّح: مراجعة كل ملف واختبار كل مضيف يدويًا.","ladder.rung.v1.0.0":"الإصدار النهائي — وأول تنزيلات يقدّمها هذا الموقع على الإطلاق.","ladder.rung.v1.1.0":"وحدة تغذية المستندات: انسخ مجلدًا كاملًا دفعة واحدة.","ladder.rung.v1.3.0":"نسخ النوتة: MusicXML وطباعة على المدرج الموسيقي.","ladder.rung.v1.4.0":"جسور إلى منتجات Freally الأخرى.","ladder.rung.v1.5.0":"Pro Tools كمكوّن إضافي (AAX)، إن سمحت شروط Avid بذلك لمنتج مجاني.","ladder.rung.v1.6.0":"نسخ الغروف الإيقاعي، ونسخ تقريبية للمسارات المنفصلة بلا ذكاء اصطناعي.","ladder.note":"الإصدار المكتمل مبنيّ ومُوسوم. إنه ليس تنزيلًا: لا يوجد أي منها، ولن يوجد حتى الإصدار 1.0.0.","honest.title":"الأشياء التي تضعها معظم المواقع في الأسفل","honest.transcription.title":"نسخة MIDI لمزيج صوتي هي تدوين نوتة","honest.transcription.body":"إيجاد النغمات في مزيج صوتي نهائي أمر صعب، ويقوم به Flipcopy بمعالجة إشارة كلاسيكية بدلًا من نموذج. سيفوّت بعض النغمات ويسمع بعضها وهي غير موجودة. يطبع ما وجده، ويذكر ما لم يستطع فعله.","honest.chords.title":"تعود الأكوردات كتتابع","honest.chords.body":"يُطبع جزء الأكوردات كالتتابع الذي يتبعه، لا كالتوزيع الدقيق الذي عُزف، وتذكر الصفحة ذلك صراحةً.","honest.downloads.title":"لا توجد تنزيلات قبل 1.0.0","honest.downloads.body":"لا نسخة تجريبية على هذه الصفحة، ولا بناء مسبق، ولا وصول مبكر. آلة نسخ تعمل بنصف كفاءتها أسوأ من آلة لم تُصنع بعد.","honest.network.title":"لا تتصل بالإنترنت أبدًا","honest.network.body":"لا يحتوي المكوّن الإضافي ولا التطبيق المستقل على أي شيفرة شبكة على الإطلاق، وتفشل بوابة بناء إذا أُضيفت أي شيفرة من هذا القبيل. قد يضيف إصدار لاحق فحص تحديثات يكون مطفأً ما لم تُفعّله بنفسك، ويشغّله برنامج منفصل.","site.tagline":"ضعه على الزجاج. اضغط START. اسحب النسخة.","footer.licence":"ملكية خاصة — جميع الحقوق محفوظة. © Mike Weaver. الاستخدام مجاني اليوم؛ وقد تُباع الإصدارات المستقبلية. ليس مفتوح المصدر.","footer.yours":"النسخ التي تصنعها ملك لك، بقدر ما كانت الملفات التي نسختها ملكًا لك لاستخدامها. لا يدّعي مؤلف Flipcopy أي ملكية لها.","featuresPage.lead":"آلة نسخ لمقاطعك. صوت في الداخل، MIDI في الخارج، مقسَّمًا إلى أجزائه؛ MIDI في الداخل، صوت في الخارج، عبر آلات حقيقية — وكل نسخة تُسحب مباشرةً إلى الـ DAW الخاص بك.","featuresPage.version":"تصف هذه الصفحة الإصدار 1.0 من Freally Flipcopy: كل ما فيها موجود في 1.0، ولا شيء مما هو مخطط له بعد 1.0 موجود فيها.","featuresPage.numbers.directions":"اتجاهان: صوت ← MIDI وMIDI ← صوت","featuresPage.numbers.parts":"أنواع من الأجزاء ينسخها: الطبول والباص واللحن واللحن المضاد والأكوردات وخط غنائي","featuresPage.numbers.instruments":"آلة موسيقية تُعزف عبرها نسخة MIDI","featuresPage.numbers.bars":"مازورة: أطول لوب يقبله الزجاج","featuresPage.numbers.formats":"صيغ ملفات يكتبها: MIDI وWAV وAIFF وFLAC وMP3","featuresPage.numbers.plugins":"صيغ مكوّنات إضافية، إضافةً إلى تطبيق مستقل","featuresPage.numbers.systems":"أنظمة تشغيل: Windows وmacOS وLinux","featuresPage.numbers.languages":"لغة","featuresPage.numbers.ai":"نماذج ذكاء اصطناعي","featuresPage.numbers.price":"السعر اليوم","featuresPage.free.title":"مجاني اليوم","featuresPage.free.body":"كل ما يفعله Flipcopy اليوم مجاني، للجميع: لا فئة مدفوعة، ولا اشتراك، ولا حساب، ولا فترة تجريبية تنتهي. النسخ التي تصنعها ملك لك، بقدر ما كانت الملفات التي نسختها ملكًا لك لاستخدامها.","featuresPage.cards.title":"ما يفعله الإصدار 1.0","featuresPage.cards.copier.title":"آلة النسخ","featuresPage.cards.copier.body":"آلة نسخ واقعية الصورة، مُصوَّرة في Blender، بأصواتها الخاصة. ضع مقطعًا على الزجاج فتطبع الشيء الحقيقي — الموجة الصوتية، أو كل نغمة — مع بياناته: السرعة، والطول، والنغمات أو المستويات.","featuresPage.cards.start.title":"وحده زر START الأخضر ينسخ","featuresPage.cards.start.body":"إفلات مقطع لا يفعل سوى وضعه على الزجاج. لا يُنسخ شيء حتى تضغط START؛ يلغي STOP المسح، ويُفرغ HOME الزجاج، لذا لا يحدث شيء لم تطلبه.","featuresPage.cards.audioToMidi.title":"صوت ← MIDI، مقسَّمًا إلى أجزاء","featuresPage.cards.audioToMidi.body":"يخرج اللوب على هيئة الأجزاء التي فيه — الطبول على صفوفها الخاصة، والباص، واللحن، ولحن مضاد حيثما وُجد، وتتابع الأكوردات — صفحة وملف MIDI لكل منها، من مسح واحد. الجزء غير الموجود لا يحصل على صفحة. أو انسخ خطًا غنائيًا بمفرده.","featuresPage.cards.midiToAudio.title":"MIDI ← صوت، عبر آلات حقيقية","featuresPage.cards.midiToAudio.body":"ملف MIDI يُعزف عبر أي من الآلات الـ 1,648 التي يستخدمها Freally MIDI Master — صوت لكل جزء وآلة إيقاع للطبول — ويُطبع صفحةَ صوت لكل جزء، إضافةً إلى المزج الكامل. WAV أو AIFF أو FLAC أو MP3، بمعدل العيّنات وعمق البت اللذين تختارهما.","featuresPage.cards.drag.title":"اسحب النسخة","featuresPage.cards.drag.body":"كل صفحة تحمل إطارًا أخضر فسفوريًا: أمسكه وأفلت الملف على مسار. أو اسحب الرزمة كلها — يصل «كل الأجزاء» مسارًا لكل جزء، و«المزج الكامل» مقطعًا واحدًا. يُسمّى كل ملف بالطريقة التي ينبغي أن يعرضه بها الـ DAW الخاص بك، مثل Loop - Bassline - 120 BPM - C# Minor.","featuresPage.cards.copies.title":"النسخ باقية إلى الأبد","featuresPage.cards.copies.body":"كل نسخة ملف حقيقي ومُتحقَّق منه في مجلد النسخ — مرقَّم، ولا يُنقل أو يُستبدل أو يُحذف أبدًا، لذا لا يفقده أي مشروع يستخدمه. تصفّح كل نسخة صنعتها، واحفظ إحداها من جديد، واعرضها في مجلدها، أو أعدها إلى الزجاج.","featuresPage.cards.browser.title":"المتصفح ومشغّل المعاينة","featuresPage.cards.browser.body":"متصفح ملفات من Freally Oscillate: حتى 128 مجلدًا، ورجوع وتقدّم، ووسوم، ونجوم، وتنقّل بلوحة المفاتيح. تعرض المعاينة الموجة الصوتية الحقيقية أو النغمات، وتشغّل MIDI بالصوت نفسه الذي تستخدمه النسخة، وتشغّل رزمة مكتملة بتزامن، مع مقارنة A/B بالأصل.","featuresPage.cards.studio.title":"الاستوديو","featuresPage.cards.studio.body":"افتح أي نسخة في لفافة بيانو، بعلامة تبويب لكل جزء، وحرّرها تمامًا كما في Freally MIDI Master. استمع إليها بأي آلة، وشكّلها على خلاط بمقابض واقعية، واعزفها بطقم طبولك أو بإحدى عيّناتك، وأرسل التعديل إلى الزجاج ليُطبع كنسخة جديدة.","featuresPage.cards.settings.title":"الإعدادات على الشاشة اللمسية","featuresPage.cards.settings.body":"تحمل شاشة آلة النسخ نفسها إعدادات النسخ: أي الأجزاء، والشبكة والسوينغ، والسرعة ومصدرها، وصوت كل جزء، وصيغة الملف، والذيل. وتتحقق بوابة بناء من أن كل إعداد يغيّر النسخة فعلًا.","featuresPage.cards.daw.title":"في كل DAW","featuresPage.cards.daw.body":"CLAP وVST3 على Windows وmacOS وLinux، وAU على macOS، وتطبيق مستقل للعمل بلا DAW — ولبرنامج Pro Tools، بالسحب. يُحفظ مع مشروعك، وآمن في مثيلات عديدة في آنٍ واحد، وقادر على المسح مباشرةً من مسار.","featuresPage.cards.skins.title":"السمات، فاتحة وداكنة","featuresPage.cards.skins.body":"خمس سمات، كل منها هيكل بارز مُصيَّر في Blender تتشاركه كل تطبيقات Freally، بنسختين فاتحة وداكنة، إلى جانب وضعين فاتح وداكن بسيطين. تُصيَّر آلة النسخ من جديد لكل سمة، فتقف دائمًا على أرضيتها الخاصة.","featuresPage.cards.offline.title":"بلا اتصال، خاص، بلا ذكاء اصطناعي","featuresPage.cards.offline.body":"لا قياس عن بُعد ولا نموذج. تُصنع كل نسخة بمعالجة إشارة كلاسيكية، ولا يتصل المكوّن الإضافي ولا التطبيق بالإنترنت أبدًا. الاستثناء الوحيد فحص تحديثات يبقى مطفأً ما لم تُشغّله بنفسك، وينفّذه برنامج منفصل.","featuresPage.compare.title":"جنبًا إلى جنب مع الأدوات التجارية","featuresPage.compare.intro":"Freally Flipcopy 1.0 بجانب الأدوات التجارية التي يستخدمها المنتجون لتحويل الصوت إلى MIDI وMIDI إلى صوت. كل خانة لمنتج آخر مأخوذة من صفحات صانعه نفسه، وقد رُوجعت في 1 أكتوبر 2026، والأسعار هي أسعار القائمة الأمريكية كما في أكتوبر 2026.","featuresPage.compare.feature":"الميزة","featuresPage.compare.row.price":"السعر (USD، أكتوبر 2026)","featuresPage.compare.freeToday":"مجاني اليوم","featuresPage.compare.row.audioToMidi":"يحوّل الصوت إلى MIDI","featuresPage.compare.legend.yes":"متوفر","featuresPage.compare.row.parts":"لوب واحد مقسَّم إلى أجزائه، لكل منها ملف MIDI خاص","featuresPage.compare.legend.no":"غير متوفر","featuresPage.compare.note.byPitch":"يفصل النغمات، لا الآلات","featuresPage.compare.note.byInstrument":"حسب الآلة","featuresPage.compare.legend.partly":"جزئيًا","featuresPage.compare.note.byHand":"المسارات المنفصلة أولًا، ثم كلٌّ يدويًا","featuresPage.compare.row.midiToAudio":"يحوّل MIDI إلى صوت عبر آلات مدمجة","featuresPage.compare.legend.unknown":"لم يُتحقَّق منه","featuresPage.compare.note.playbackOnly":"يشغّله، لكنه لا يصدّر صوتًا","featuresPage.compare.row.drag":"اسحب النتيجة مباشرةً إلى مسار في DAW","featuresPage.compare.note.ara":"في بعض برامج DAW، عبر ARA","featuresPage.compare.row.plugin":"يعمل داخل DAW كمكوّن إضافي","featuresPage.compare.note.link":"يرسل الصوت إلى تطبيقه الخاص","featuresPage.compare.note.ownDaw":"الـ DAW الخاص به فقط","featuresPage.compare.note.appOnly":"تطبيق مستقل فقط","featuresPage.compare.row.systems":"Windows وmacOS وLinux","featuresPage.compare.row.noAi":"بلا ذكاء اصطناعي ولا تعلّم آلي","featuresPage.compare.note.aiStems":"يستخدمه لفصل المسارات","featuresPage.compare.summaryTitle":"باختصار","featuresPage.compare.summary":"باختصار: وحده Flipcopy يملك كل ذلك — الاتجاهان، والأجزاء، والسحب، والمكوّن الإضافي، والأنظمة الثلاثة، وبلا ذكاء اصطناعي.","featuresPage.compare.theyWinTitle":"أين يتفوّقون","featuresPage.compare.theyWin":"حيث يتفوّقون: يستطيع Melodyne Studio وRipX وAnthemScore وAbleton Live كتابة النغمات المنفردة لأكورد من تسجيل متعدد الأصوات (Melodyne فقط من آلة سُجّلت بمفردها)؛ أما Flipcopy فيعطيك التتابع بدلًا من ذلك، ويقول ذلك. كما يفصل RipX وAbleton Live Suite وLogic Pro المزيج إلى مسارات صوتية منفصلة، وهو ما لا يفعله Flipcopy 1.0.","featuresPage.compare.asOf":"عمود Flipcopy هو الإصدار 1.0، الذي لم يصدر بعد، وسعره هو سعر اليوم: Flipcopy مجاني اليوم، وقد تُباع الإصدارات المستقبلية. والمنتجات الأخرى تتغير أيضًا؛ هذا الجدول كما في 1 أكتوبر 2026.","featuresPage.why.title":"لماذا بُني بهذه الطريقة","featuresPage.why.dsp.title":"معالجة إشارة كلاسيكية","featuresPage.why.dsp.body":"رصد بدايات النغمات، وتتبّع طبقة الصوت، والكروما، ومُصيِّر حتمي، بلا أي نموذج في أي مكان. الملف نفسه والإعدادات نفسها والإصدار نفسه تعطي النسخة نفسها، بايتًا ببايت، في كل مرة.","featuresPage.why.print.title":"ما تراه هو ما تسحبه","featuresPage.why.print.body":"تُرسم كل صفحة من بايتات الملف الذي تسحبه. النغمات والسرعة والطول على الورق هي النغمات والسرعة والطول التي تصل إلى مسارك.","featuresPage.why.honest.title":"نسخ صادقة","featuresPage.why.honest.body":"لا صفحات فارغة ولا تخمينات متنكّرة في هيئة تدوين نوتة. الأكوردات تقول إنها تتابع، والمقطع الأطول من أن يتسع له الزجاج يُرفض مع ذكر طوله بدلًا من قصّه، والخط الغنائي المتروك كما هو يقول ذلك.","featuresPage.why.local.title":"يبقى على جهازك","featuresPage.why.local.body":"لا قياس عن بُعد ولا سحابة. ملفاتك ونسخك لا تغادر جهازك أبدًا، وتفشل بوابة بناء إذا أُضيفت يومًا شيفرة شبكة إلى المكوّن الإضافي أو التطبيق.","featuresPage.why.tempo.title":"يتبع الـ DAW الخاص بك","featuresPage.why.tempo.body":"يقرأ المكوّن الإضافي سرعة مشروعك ولا يغيّرها أبدًا، وكل سرعة يطبعها Flipcopy تذكر مصدرها: اللوب، أو الملف، أو اسمه، أو الـ DAW الخاص بك، أو أنت.","featuresPage.why.mix.title":"لا شيء يصل إلى مزيجك بالخطأ","featuresPage.why.mix.body":"تُعزف أصوات آلة النسخ والمعاينة بهدوء عبر المكوّن الإضافي، ولا تدخل التصدير أبدًا. وحين تصمت، يمرّ صوت مسارك دون أن يُمسّ.","featuresPage.coming.title":"ما الذي لم يأتِ بعد","featuresPage.coming.intro":"نقولها بوضوح، لأن قائمة ميزات تخفي ثغراتها لا تستحق القراءة. هذه الصفحة هي الإصدار 1.0، ويُبنى Flipcopy درجةً درجة: ليس كل ما فيها مبنيًا بعد. كل درجة على الطريق إلى 1.0 موسومة بحالتها.","featuresPage.limits.title":"ما لا يفعله الإصدار 1.0","featuresPage.limits.chords":"لا يكتب كل نغمة من أكورد مسموع في تسجيل ممزوج: تعود الأكوردات كتتابع، وتذكر الصفحة ذلك.","featuresPage.limits.loops":"ينسخ اللوبات، لا الأغاني الكاملة: يقبل الزجاج مقاطع حتى 16 مازورة، ويرفض الأطول منها مع ذكر طوله.","featuresPage.limits.stems":"لا يفصل تسجيلًا ممزوجًا إلى مسارات صوتية منفصلة: تخرج أجزاء اللوب بصيغة MIDI.","featuresPage.limits.aax":"ليس مكوّنًا إضافيًا لـ Pro Tools: في Pro Tools، استخدم التطبيق المستقل واسحب النسخة إلى الخط الزمني.","featuresPage.coming.downloads":"لا توجد تنزيلات قبل الإصدار 1.0، ولا شيء منها على هذه الصفحة.","docs.intro":"يكبر هذا الدليل مع كل إصدار. يغطي الآن ما يفعله الإصدار 0.5.0، ويصل الدليل المصوَّر الكامل، مع لقطة شاشة لكل خطوة، مع الإصدار التجريبي.","docs.start.title":"البدء","docs.agreement.title":"اتفاقية الترخيص","docs.window.title":"النافذة","docs.copier.title":"صنع نسخة","docs.screen.title":"الشاشة اللمسية","docs.copySettings.title":"إعدادات النسخ","docs.instruments.title":"الآلات الموسيقية","docs.copies.title":"نسخك","docs.browser.title":"المتصفح","docs.preview.title":"مشغّل المعاينة","docs.settings.title":"الإعدادات","docs.report.title":"عندما يحدث خطأ ما","docs.privacy.title":"الخصوصية والشبكة","docs.start.p1":"يعمل Flipcopy داخل الـ DAW الخاص بك كمكوّن إضافي من نوع CLAP أو VST3 أو AU، أو بمفرده كتطبيق مستقل. ضعه على أي مسار صوتي: فهو يمرّر صوت المسار تمامًا كما يصل، لذا من الآمن تركه في مكانه.","docs.start.p2":"لا توجد تنزيلات قبل الإصدار 1.0.0، والشيفرة المصدرية خاصة.","docs.agreement.p1":"عند فتح Flipcopy لأول مرة، يعرض اتفاقية الترخيص الخاصة به. اقرأها حتى النهاية فيصبح زر موافق متاحًا. وحتى توافق، لا يقرأ Flipcopy شيئًا، ولا ينسخ شيئًا، ولا يضيف شيئًا إلى صوت مسارك.","docs.agreement.p2":"تُحفظ إجابتك على جهازك وتشترك فيها كل نسخة مفتوحة من Flipcopy، في كل DAW وفي التطبيق المستقل. إذا رفضت، اختر اقرأها مرة أخرى متى صرت مستعدًا.","docs.window.p1":"على أحد الجانبين المتصفح، ومشغّل المعاينة مثبَّت أسفله. وبقية النافذة هي المسرح، حيث تقف آلة النسخ. اسحب الخط الفاصل بينهما لتوسيع المتصفح أو تضييقه، أو ركّز عليه واستخدم مفاتيح الأسهم.","docs.window.p2":"اضغط Ctrl+B (أو Cmd+B على Mac)، أو الزر الموجود على حافة المتصفح، لطيّ المتصفح ومعاينته جانبًا: فيشغل المسرح النافذة كلها. اضغط مرة أخرى فيعودان بالعرض الذي تركتهما عليه. ويتذكّر Flipcopy ما اخترته.","docs.copier.p1":"ضع ملف صوت أو MIDI على الزجاج: أفلِته من مستكشف الملفات أو Finder في أي مكان من النافذة، أو اسحبه من المتصفح أو من شريط المعاينة إلى آلة النسخ، أو اضغط Enter على صف في المتصفح، أو اضغط Enter على الزجاج الفارغ لاختيار ملف. تطبع آلة النسخ الأصل وتضعه على الزجاج ووجهه إلى الأسفل. ووضع ملف على الزجاج لا يبدأ النسخ أبدًا.","docs.copier.p2":"اضغط مفتاح START الأخضر، أو Ctrl+Enter (أو Cmd+Enter على Mac). يُغلق الغطاء، ويمر المصباح، وتنزلق النسخة إلى الدرج: تخرج الحلقة الصوتية بصيغة MIDI، صفحةً لكل جزء تسمعه آلة النسخ؛ ويخرج ملف MIDI صوتًا، صفحةً لكل جزء. يلغيها Esc أو مفتاح STOP الأحمر، ويُفرغ مفتاح HOME الرمادي الزجاج.","docs.copier.p3":"كل صفحة ملف حقيقي في مجلد النسخ لديك (المستندات/Freally Flipcopy/Copies، ما لم تختر مجلدًا آخر في الإعدادات)، مرقَّم، ولا يُنقل أو يُستبدل أو يُحذف أبدًا. أمسك الصفحة من الإطار الأخضر الليموني حول مقطعها المطبوع واسحبها مباشرة إلى مسار في DAW، أو اسحب الرزمة كلها دفعة واحدة.","docs.copier.p4":"تُعزف أصوات آلة النسخ بهدوء عبر مخرج الإضافة نفسه، لا أثناء تشغيل DAW ولا في التصدير أبدًا. أوقفها أو اخفضها من الإعدادات.","docs.screen.p1":"تقول شاشة آلة النسخ ما تفعله وفي أي اتجاه تنسخ: صوت > MIDI أو MIDI > صوت. وتحتها مفاتيحها اللمسية. يفتح المفتاح «إعدادات» لوحة «إعدادات النسخ»؛ ويتنقّل ◀ «السابق» و«التالي» ▶ بين نسخك؛ وتعمل «حفظ» و«إظهار» و«إعادة طبع» على النسخة الموجودة في الدرج. ولا يبدأ أيٌّ منها النسخ: وحده START يفعل ذلك.","docs.screen.p2":"عندما لا تكون لملف MIDI سرعة خاصة به لكن اسمه يذكر واحدة، مثل Hook 127 BPM.mid، تعرضها عليك شريحة صغيرة بجانب الشاشة. ينسخ «استخدم 127 BPM» ذلك الملف بتلك السرعة؛ أما «أبقِ سرعة المشروع» فيتجاهل العرض. لا يغيّر Flipcopy سرعة الـ DAW الخاص بك أبدًا، وتطبع كل صفحة سرعتها ومصدر تلك السرعة.","docs.copySettings.p1":"اضغط «إعدادات» على الشاشة اللمسية فتنبثق منها اللوحة. كل إعداد يغيّر النسخة التي تصنعها، والتغيير يسري على النسخة التالية، لا على نسخة قيد الإنشاء أبدًا؛ ويحتفظ مشروعك بالإعدادات. ينقلك Tab عبر اللوحة، وتختار بمفاتيح الأسهم، ويغلقها Esc.","docs.copySettings.p2":"للحلقة الصوتية، يختار «الأجزاء» ما يُنسخ: كل الأجزاء، صفحة لكل جزء؛ أو جزءًا واحدًا فقط: الطبول أو خط الباص أو اللحن أو الأكوردات؛ أو الخط الغنائي، نوتةً واحدة في كل مرة. وإذا لم تحتوِ الحلقة على شيء من الجزء الذي طلبته، تقول آلة النسخ ذلك بدلًا من طباعة صفحة فارغة. وتضع «الشبكة» النوتات على 1/8 أو 1/16 أو 1/32 أو 1/16T، أو تتركها «كما قُرئ»، ويُبقي «السوينغ» على التأرجح أو يقوّمه.","docs.copySettings.p3":"لملف MIDI، تختار «الصفحات» صفحةً لكل جزء أو «المزيج فقط»، ويحدد «الذيل» كم يستمر رنين الصوت بعد آخر نوتة. وتكتب «الصيغة» ملفات WAV أو AIFF أو FLAC أو MP3 (320 kbps)، بمعدل العينة الخاص بالمشروع أو بـ 44.1 أو 48 أو 88.2 أو 96 kHz، بعمق 16 أو 24 بت أو 32 بت عائم. لا تدعم FLAC وAIFF الفاصلة العائمة، لذا تُكتبان بعمق 24 بت؛ وتُكتب MP3 بتردد 44.1 أو 48 kHz.","docs.copySettings.p4":"في الاتجاهين، تكون «السرعة» «تلقائية»، أو «سرعة المشروع»، أو «سرعة الملف نفسه»، أو «من اسم الملف»، أو سرعةً تحدّدها أنت عبر «حدّدها بنفسك».","docs.instruments.p1":"تعزف نسخة MIDI كل جزء عبر آلة موسيقية من مكتبة Freally، وهي المكتبة نفسها التي يستخدمها Freally MIDI Master. في «إعدادات النسخ»، اكتب في مربع البحث الخاص بجزء ما لتعثر على آلة باسمها أو نوعها الموسيقي أو عائلتها، وأضف رقمًا لتطلب أحد تنويعاتها، ثم اخترها: يمكن أن يكون لكلٍّ من خط الباص واللحن واللحن المضاد والأكوردات آلته الخاصة. Preview Piano هي الآلة الافتراضية. وتُعزف الطبول عبر آلة الإيقاع التي تختارها: Preview Kit افتراضيًا، أو 808 أو 707 أو 606.","docs.instruments.p2":"تطبع كل صفحة صوت الآلةَ التي عُزفت بها على سطر «الحبر»، بجانب سرعتها.","docs.copies.p1":"يتنقّل المفتاحان ◀ «السابق» و«التالي» ▶ على الشاشة اللمسية، أو [ و] على لوحة المفاتيح، بين كل النسخ التي صنعتها صفحةً صفحة؛ وكل منها مستقرة في الدرج، جاهزة للسحب. يحفظ المفتاح «حفظ» الصفحة العليا كملف جديد، أينما اخترت وبالصيغة التي تحددها. ويُظهر «إظهار» النسخة في مجلدها. ويعيد «إعادة طبع» أصل النسخة إلى الزجاج بالإعدادات التي صُنعت بها: اضغط START لتصنعها من جديد.","docs.copies.p2":"اسحب صفحة عائدًا بها إلى الزجاج، أو أفلِت واحدة من «النسخ»، فتوضع عليه كأصل، جاهزةً لتُنسخ في الاتجاه الآخر؛ وتذكر النسخة الجديدة الصفحة التي جاءت منها. ولسحب عدة صفحات دفعة واحدة، انقرها مع الضغط على Shift، ثم اسحب إحداها: فتذهب كلها، بترتيب الصفحات.","docs.copies.p3":"يحتوي مجلد كل نسخة على ملف ticket.txt، وهو سجل بنص عادي يبيّن كيف صُنعت: الأصل وبصمته، والإعدادات، والسرعة ومصدرها، والآلات الموسيقية، وملف كل صفحة وبصمته.","docs.browser.p1":"يُفتح المتصفح على فئاته: «النسخ»، وهي كل صفحة ومزيج صنعته، و«الأخيرة»، وهي الأصول التي وضعتها مؤخرًا على الزجاج. وتحتها المجلدات التي أضفتها؛ اختر «+ إضافة مجلد» لإضافة مجلد، حتى 128 مجلدًا. والمجلد الموجود على محرك أقراص غير موصول يحتفظ بمكانه ويقول إنه غير متصل الآن. لإيقاف تصفح مجلد، انقر عليه بزر الفأرة الأيمن، أو حدّده واضغط Delete؛ لا يُمسّ أي شيء على القرص.","docs.browser.p2":"افتح مجلدًا لتتنقّل فيه كشجرة. اكتب لتصفيته بالاسم، واختر وسمًا أو «المميّزة بنجمة» لتضييقه، واختر «إظهار كل الملفات» لترى الملفات المرافقة التي يخفيها Flipcopy، مثل .asd و .reapeaks. ويأخذك «رجوع» و«للأمام» عبر الأماكن التي زرتها.","docs.browser.p3":"تنقّل بين الصفوف بالمفتاحين ↑ و↓: كل صف تصل إليه يُشغَّل مرة واحدة في المعاينة. يفتح → مجلدًا ويغلقه ←. ويضع Enter الملف المحدد على الزجاج، وكذلك سحب صفه إلى آلة النسخ.","docs.browser.p4":"في المرة الأولى التي تضيف فيها مجلدًا، يعدّ Flipcopy ملفاته، مع شريط يبيّن إلى أين وصل. ويقرأ حتى عمق 12 مستوى من المجلدات وحتى 50,000 ملف، ولا يتبع أبدًا اختصارًا يقود إلى خارج المجلد.","docs.preview.p1":"يقع مشغّل المعاينة أسفل المتصفح. يعرض ملف الصوت موجته الصوتية الحقيقية. ويعرض ملف MIDI نغماته ويُعزف عبر Preview Piano، وهو الصوت نفسه الذي تستخدمه النسخة ما لم تختر غيره، فتسمع كيف ستبدو النسخة.","docs.preview.p2":"مفتاح المسافة يشغّل ويوقف مؤقتًا، و«إيقاف» يعود إلى البداية، والنقر أو السحب على الشريط يحرّك رأس التشغيل. و«تكرار» يكرّر الملف، و«التشغيل عند التحديد» (السماعات) يشغّل كل ملف تحدده، والمنزلق يضبط المستوى. تُعزف المعاينة عبر مخرج Flipcopy نفسه ولا تدخل التصدير أبدًا. يُشغَّل ملف WAV بأي طول؛ أما الملف بصيغة أخرى فيُشغَّل إذا كانت مدته خمس دقائق أو أقل.","docs.preview.p3":"انقر الأصل على الزجاج، أو صفحة على الدرج، لتسمعه. وعندما تكتمل النسخة، يشغّل «النسخة» كل صفحاتها معًا ويشغّل «الأصل» الملف الموجود على الزجاج، من الموضع نفسه في الموسيقى، لتسمع الفرق قبل أن تسحب. والتشغيل ليس مطلوبًا أبدًا: يمكن سحب الصفحات بمجرد أن تستقر آخرها.","docs.preview.p4":"يرتدي الشريط الإطار الأخضر الليموني نفسه الذي ترتديه الصفحة. اسحبه إلى الزجاج لتضع ذلك الملف هناك.","docs.settings.p1":"افتح «الإعدادات» من أيقونة الترس أعلى المتصفح. يشغّل «أصوات الآلة» أصوات آلة النسخ أو يوقفها، ويضبط مستواها ويبقيها صامتة أثناء تشغيل الـ DAW. ومفتاح مستقل يوقف الأصوات الناعمة التي تُصدرها اللوحات ومربعات الحوار عند فتحها وإغلاقها.","docs.settings.p2":"تحت «الحركة»، يشغّل «سريعة» الآلة بتوقيتاتها القصيرة، مع بقاء كل صوت في موضعه. ويتبع «تقليل الحركة» إعداد نظامك، أو اختر «تقليل» ليكون مفعّلًا دائمًا: لا انقلاب للصفحة، ولا تأرجح للغطاء، ولا مرور للمصباح، ولا تعتيم للغرفة. وتظل آلة النسخ تعرض كل خطوة وتُسمِع كل صوت، ويبقى START الطريقة الوحيدة لصنع نسخة.","docs.settings.p3":"يُظهر «مجلد النسخ» المكان الذي تذهب إليه نسخك. ويختار «تغيير…» مجلدًا آخر: تذهب النسخ الجديدة إليه، وتبقى النسخ المصنوعة سابقًا حيث هي. ويفتحه «إظهار في المجلد». ويعرض «حول» الإصدار، وتراخيص الجهات الخارجية، واتفاقية الترخيص.","docs.report.p1":"إذا أخفق Flipcopy نفسه، كنسخة لم يتمكن من كتابتها، تعرض الشاشة «الإبلاغ». فيفتح صفحة في متصفح الويب لديك تبيّن بالضبط ما يحتويه البلاغ؛ ولا يُرسَل شيء ما لم تضغط «إرسال» هناك. أما الملف الذي ترفضه آلة النسخ لأنه طويل جدًا أو صامت أو ليس صوتًا، فليس إخفاقًا، وتقول الشاشة السبب بدلًا من ذلك.","docs.privacy.p1":"لا يملك Flipcopy حسابًا ولا قياسًا عن بُعد، ولا يحتوي المكوّن الإضافي ولا التطبيق المستقل على أي شيفرة شبكة على الإطلاق. ملفاتك ونسخك لا تغادر جهازك أبدًا.","docs.privacy.p2":"لا يحتوي على أي ذكاء اصطناعي من أي نوع: تُصنع كل نسخة بمعالجة إشارة كلاسيكية وحتمية، وتفشل بوابة بناء إذا أُضيفت يومًا مكتبة تعلّم آلي.","kit.skip":"الانتقال إلى المحتوى","kit.nav.site":"الموقع","kit.nav.home":"الرئيسية","kit.nav.features":"الميزات","kit.nav.documentation":"التوثيق","kit.nav.changelog":"سجل التغييرات","kit.nav.language":"اللغة","kit.nav.allApps":"كل تطبيقات Freally","kit.badge.progress":"v0.5.0 منجز · v0.5.5 هو التالي","kit.cta.features":"شاهد كل الميزات","kit.cta.docs":"اقرأ التوثيق","kit.price":"Freally Flipcopy مجاني اليوم، لكنه قد لا يبقى مجانيًا إلى الأبد: قد تُباع الإصدارات المستقبلية.","kit.noDownloads":"لا توجد تنزيلات بعد، والشفرة المصدرية خاصة.","kit.label.overview":"نظرة عامة","kit.label.inAction":"أثناء العمل","kit.label.inside":"في الداخل","kit.label.roadmap":"خارطة الطريق","kit.ladder.done":"منجز","kit.ladder.planned":"مخطط له","kit.ladder.goal":"الهدف","kit.ladder.later":"لاحقًا","kit.label.honesty":"الصراحة","kit.family.label":"عائلة Freally","kit.family.title":"<span class=\"hl-muted\">عائلة واحدة.</span> <span class=\"hl-bright\">ثمانية تطبيقات.</span>","kit.cta.label":"ما الذي تغيّر","kit.cta.title":"<span class=\"hl-muted\">كل إصدار،</span> <span class=\"hl-bright\">مدوَّن.</span>","kit.cta.lede":"يسرد سجل التغييرات كل ما تغيّر في Freally Flipcopy، إصدارًا بعد إصدار، بثماني عشرة لغة.","kit.cta.changelog":"اقرأ سجل التغييرات","kit.footer.thisApp":"هذا التطبيق","kit.footer.family":"عائلة Freally","kit.status.devVersion":"قيد التطوير · v0.5.0","kit.head.features":"<span class=\"hl-muted\">كل ما يفعله،</span> <span class=\"hl-bright\">جنبًا إلى جنب.</span>","kit.label.numbers":"بالأرقام","kit.numbers.lead":"كل رقم محسوب من التطبيق نفسه. لا شيء مُقدَّر، ولا شيء مُقرَّب إلى الأعلى.","kit.label.free":"مجاني اليوم","kit.label.compare":"مقارنة","kit.label.principles":"المبادئ","kit.label.limits":"الحدود","kit.states.title":"ماذا تعني الحالات","kit.states.done":"مبنيّ وموسوم، لكنه ليس تنزيلًا على هذا الموقع","kit.states.planned":"لم يُبنَ بعد","kit.states.goal":"الإصدار الذي يقود إليه الطريق","kit.states.later":"بعد ذلك، ولم يُجدوَل بعد","kit.states.ladder":"شاهد كل درجة على الطريق","kit.head.documentation":"<span class=\"hl-muted\">كيف يعمل،</span> <span class=\"hl-bright\">خطوة بخطوة.</span>","kit.search.placeholder":"ابحث في التوثيق","kit.docs.contents":"المحتويات","kit.head.changelog":"<span class=\"hl-muted\">كل تغيير،</span> <span class=\"hl-bright\">إصدارًا بعد إصدار.</span>","kit.changelog.lede":"الأحدث أولًا: كل ما تغيّر في Freally Flipcopy، بكل لغة يتحدث بها هذا الموقع.","kit.changelog.versions":"الإصدارات","kit.search.none":"لا شيء في هذا الموقع يطابق ذلك.","kit.zoom.close":"إغلاق","changelog.438e4f8ca3fc":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.0</span><time class=\"release__date\" datetime=\"2026-10-05\">2026-10-05</time></span><span class=\"release__title\">الشاشة اللمسية</span>","changelog.63f032bc62d6":"تدبّ الحياة في الشاشة اللمسية لآلة النسخ. تنفتح منها <strong>إعدادات النسخ</strong> — أي الأجزاء تُنسخ، والشبكة، والسوينغ، والسرعة، والآلات الموسيقية، والصيغة — وكل إعداد يغيّر النسخة التي تصنعها؛ وتتنقّل مفاتيح الشاشة بين نسخك، وتحفظها، وتُظهرها، وتطبعها من جديد؛ ويمكن للنسخة أن تعود إلى الزجاج لتُنسخ في الاتجاه الآخر.","changelog.6b02e0d363a4":"الإضافات","changelog.fe9572610f3a":"<strong>إعدادات النسخ.</strong> اضغط <strong>إعدادات</strong> على الشاشة اللمسية فتنبثق منها اللوحة. للوب الصوتي: انسخ <strong>كل الأجزاء</strong>، أو جزءًا واحدًا <strong>فقط</strong> (الطبول أو خط الباص أو اللحن أو الأكوردات — ويُرفض الطلب، ولا تُطبع صفحة فارغة أبدًا، إذا لم يحتوِ اللوب على شيء منه)، أو <strong>الخط الغنائي</strong> مقروءًا نوتةً واحدة في كل مرة؛ وضع النوتات على <strong>شبكة</strong> (1/8 أو 1/16 أو 1/32 أو 1/16T) و<strong>قوّم</strong> السوينغ. لملف MIDI: صفحة لكل جزء، أو <strong>المزيج فقط</strong>؛ و<strong>آلة موسيقية</strong> لكل جزء — ابحث في المكتبة بالاسم أو النوع الموسيقي أو العائلة — و<strong>آلة إيقاع</strong> (808، 909، 707، 606)؛ و<strong>الذيل</strong> بعد آخر نوتة؛ و<strong>WAV</strong> أو <strong>AIFF</strong> أو <strong>FLAC</strong> أو <strong>MP3</strong> (320 kbps)، بتردد 44.1 أو 48 أو 88.2 أو 96 kHz، بعمق 16 بت أو 24 بت أو 32 بت عائم. وفي الاتجاهين: <strong>السرعة</strong> — تلقائية، أو سرعة المشروع، أو سرعة الملف نفسه، أو السرعة المذكورة في اسم الملف، أو سرعة تحدّدها بنفسك. وتسري التغييرات على النسخة التالية، لا على نسخة قيد الإنشاء أبدًا، ويحتفظ بها المشروع.","changelog.80133c005eb5":"<strong>كل صفحة تذكر آلتها الموسيقية</strong> (الحبر …)، بجانب سرعتها ومصدر تلك السرعة.","changelog.54c5f05f9607":"<strong>سرعة اسم الملف، معروضةً عليك.</strong> ملف MIDI بلا سرعة خاصة به لكن اسمه يذكر واحدة (<em>Hook 127 BPM.mid</em>) تظهر له شريحة صغيرة بجانب الشاشة: <em>استخدم 127 BPM</em> ينسخ ذلك الملف بها؛ ولا تتغيّر سرعة المشروع أبدًا.","changelog.762dc63396b4":"<strong>الرزمة.</strong> يتنقّل ◀ <strong>السابق</strong> و<strong>التالي</strong> ▶ (أو <code>[</code> و<code>]</code>) بين نسخك، وكل منها مستقرة في الدرج جاهزة للسحب؛ ويحفظ المفتاح <strong>حفظ</strong> الصفحة العليا كملف جديد بالصيغة التي تختارها؛ ويُظهرها <strong>إظهار</strong> في مجلدها؛ ويعيد <strong>إعادة طبع</strong> أصل النسخة إلى الزجاج بالإعدادات التي صُنعت بها — اضغط START لتصنعها من جديد.","changelog.5e9b6523831f":"<strong>نسخة من نسخة.</strong> الصفحة المسحوبة عائدةً إلى الزجاج — أو المُفلَتة من «النسخ» — توضع عليه كأصل، وتذكر النسخة الجديدة الصفحة التي جاءت منها.","changelog.9c72fd49cbf7":"<strong>عدة صفحات دفعة واحدة.</strong> انقر الصفحات مع الضغط على Shift لتحديدها؛ واسحب إحداها فتذهب كلها، بترتيب الصفحات.","changelog.c754df195ab0":"<strong>البطاقة.</strong> يحتوي مجلد كل نسخة على <code>ticket.txt</code>: الأصل وبصمته، والإعدادات، والسرعة ومصدرها، والآلات الموسيقية، والجلسة التي صُنعت فيها، وملف كل صفحة وبصمته. ويعيد <code>flipc copy --ticket</code> صنع النسخة نفسها، بايتًا ببايت.","changelog.14e910f0a79b":"<strong>الإعدادات.</strong> سرعة الحركة (<strong>سريعة</strong> تشغّل الآلة بتوقيتاتها القصيرة)، و<strong>تقليل الحركة</strong> (اتباع النظام، أو دائمًا)، و<strong>مجلد النسخ</strong> (<strong>تغيير…</strong> و<strong>إظهار في المجلد</strong> — تذهب النسخ الجديدة إلى المجلد الجديد، وتبقى القديمة حيث هي)، ومفتاح مستقل لأصوات الواجهة، وتراخيص «حول» واتفاقيته.","changelog.54aac57413aa":"<strong>أصوات الواجهة.</strong> تنفتح الإعدادات وإعدادات النسخ والمتصفح وتنغلق وتختفي وتظهر بأصوات قصيرة وناعمة وزجاجية، كلٌّ منها بطول حركته تمامًا — عبر مخرج الإضافة نفسه، لا في التصدير أبدًا، وتُطفأ بمفتاحها الخاص.","changelog.49cc52f4d8b8":"<strong><code>flipc copy</code></strong> يقبل كل إعدادات النسخ: <code>--parts</code>، <code>--grid</code>، <code>--swing</code>، <code>--stems</code>، <code>--toner</code>، <code>--drums</code>، <code>--format</code>، <code>--rate</code>.","changelog.1246fc93bca0":"الإصلاحات","changelog.b58b14c86e76":"<strong>الصفحة الواقعة تحت الصفحة العليا</strong> يمكن الضغط عليها حيث تظهر خارج حافة الدرج.","changelog.b0befc5e6040":"<span class=\"release__meta\"><span class=\"release__ver\">v0.4.0</span><time class=\"release__date\" datetime=\"2026-10-05\">2026-10-05</time></span><span class=\"release__title\">متصفح الملفات ومشغّل المعاينة</span>","changelog.e884ffe2f90e":"اعثر على عيّنة أو مقطع MIDI، واستمع إليه، وانظر إليه، وضعه على الزجاج — المتصفح ومشغّل المعاينة من Freally Oscillate، بجانب آلة النسخ. كل ما هو أساسي موجود هنا: اكتمل الـ MVP.","changelog.130b73a201db":"<strong>المتصفح.</strong> يُفتح على فئاته — <strong>النسخ</strong>، وهي كل صفحة ومزيج صنعته، و<strong>الأخيرة</strong>، وهي الأصول التي وضعتها مؤخرًا على الزجاج، ولكلٍّ منهما عدّاده — ثم المجلدات التي تضيفها بـ <strong>+ إضافة مجلد</strong> (حتى 128). والمجلد الموجود على محرك أقراص مفصول يحتفظ بمكانه ويقول ذلك؛ انقر مجلدًا بزر الفأرة الأيمن، أو حدّده واضغط <code>Delete</code>، لإيقاف تصفحه، ولا يُمسّ أي شيء على القرص. ويتنقّل <strong>رجوع</strong> و<strong>للأمام</strong> عبر الأماكن التي زرتها، تمامًا كما في Freally Oscillate.","changelog.3c76294f691c":"<strong>المجلد كشجرة.</strong> وسّعه وطوِّه، واكتب لتصفيته، وضيّقه إلى وسم أو إلى ما ميّزته بنجمة، واختر <strong>إظهار كل الملفات</strong> لترى الملفات المرافقة التي يخفيها (<code>.asd</code> و<code>.reapeaks</code> وما شابهها). يتنقّل <code>↑</code>/<code>↓</code> بين الصفوف، وكل صف تصل إليه يُشغَّل مرة واحدة؛ ويفتح <code>→</code> مجلدًا، ويغلقه <code>←</code>، ويضع <code>Enter</code> الملف على الزجاج.","changelog.9e19fd75f5c5":"<strong>فهرسة يمكنك مراقبتها.</strong> يُعَدّ المجلد الجديد في خيط معالجة خاص به مع شريط يبيّن إلى أين وصل — حتى عمق 12 مستوى من المجلدات وحتى 50,000 ملف، دون أن يتبع أبدًا اختصارًا يقود إلى خارج المجلد.","changelog.7e5083732503":"<strong>مشغّل المعاينة</strong>، مثبَّت أسفل المتصفح. يعرض الصوت موجته الصوتية الحقيقية؛ ويعرض ملف MIDI نغماته ويُعزف عبر <strong>Preview Piano</strong>، وهو الصوت والتصيير نفساهما اللذان تستخدمهما النسخة، فتكون المعاينة هي النسخة. يشغّل <code>Space</code> ويوقف مؤقتًا؛ انقر الشريط أو اسحب عليه لتحريك رأس التشغيل، الذي يعدّ حتى آخر نغمة في الموسيقى، لا حتى خط المازورة أبدًا؛ ومعه التكرار والتشغيل عند التحديد ومستوى للصوت. يُبَثّ ملف WAV بأي طول؛ أما الصيغ الأخرى فتُشغَّل إذا كانت مدتها خمس دقائق أو أقل. ويُعزف عبر مخرج الإضافة نفسه ولا يدخل التصدير أبدًا.","changelog.ca065d9e7b42":"<strong>استمع إلى النسخة قبل أن تمضي.</strong> انقر الأصل على الزجاج أو أي صفحة على الدرج لمعاينتها؛ وعندما تكتمل النسخة، يشغّل <strong>النسخة</strong> كل الصفحات معًا ويشغّل <strong>الأصل</strong> الزجاج، من الموضع نفسه في الموسيقى. وهذا اختياري: تُسحب الصفحات لحظة استقرار آخرها، سواء شُغّلت أم لا.","changelog.d17537ff40ec":"<strong>السحب إلى الزجاج.</strong> صفٌّ، أو شريط المعاينة — المؤطَّر بالأخضر الليموني نفسه الذي تؤطَّر به الصفحة —، إذا سُحب إلى آلة النسخ وضع ذلك الملف على الزجاج، مع مطبوعة مصغّرة منه تتبع المؤشر. لا يبدأ شيء قبل START.","changelog.cda58c5f73eb":"<strong>أخفِ المتصفح</strong> بـ <code>Ctrl+B</code> (<code>Cmd+B</code> على Mac) أو بالزر الموجود على حافته: يشغل المسرح النافذة كلها ويعود العنوان الدوّار إلى المنتصف. ويتذكّر Flipcopy ذلك.","changelog.5d236e4be21d":"<strong>أبلغ عن مشكلة من داخل التطبيق.</strong> عندما يخفق Flipcopy نفسه، تعرض الشاشة <strong>الإبلاغ</strong>، فيفتح صفحة البلاغ في متصفح الويب لديك ويبيّن بالضبط ما تحتويه؛ ولا يُرسَل شيء ما لم تضغط «إرسال» هناك.","changelog.2a6141e43be0":"التغييرات","changelog.49de87a64bae":"<strong>موقع التوثيق</strong> مبني على عُدّة مواقع Freally المشتركة، وهي نفسها في كل مواقع Freally، ودليله محدَّث لهذا الإصدار.","changelog.b0f81c543dda":"<strong>يُعثر على الصفحة الواقعة تحت المؤشر بأي حجم للنافذة.</strong> كانت النقرة أو السحبة على صفحة تقع في المكان الخطأ بمجرد تغيير مقياس النافذة.","changelog.2096d3c4bbd8":"<span class=\"release__meta\"><span class=\"release__ver\">v0.3.0</span><time class=\"release__date\" datetime=\"2026-10-01\">2026-10-01</time></span><span class=\"release__title\">صوت ← MIDI: اللحظة السحرية</span>","changelog.df6f06284fdc":"ضع لوبًا صوتيًا على الزجاج، واضغط START، فيخرج منه MIDI — صفحة لكل طبقة تسمعها آلة النسخ، متتالية من مسح واحد، لكل منها ملفها الخاص، بإطار أخضر ليموني، تسحبها إلى الـ DAW منفردة أو جميعها معًا. ويخرج ملف MIDI متعدد الأجزاء بالطريقة نفسها: صفحة صوت لكل جزء، والملف كله كمزيج واحد.","changelog.24a7fe5481b4":"<strong>صوت ← MIDI.</strong> يُقرأ اللوب الصوتي إلى طبقاته — الطبول والباص واللحن، و<strong>لحن مضاد</strong> حين يحمل اللوب خطًا ثانيًا مستقلًا، والأكوردات — بمستخرِج MIDI Master القائم على معالجة الإشارة الكلاسيكية (بلا ذكاء اصطناعي). لكل طبقة يُعثر عليها صفحتها وملف <code>.mid</code> الخاص بها، مسمّاة كما يعرضها الـ DAW (<em>Loop - Bassline - 120 BPM - C# Minor</em>)؛ والطبقة غير الموجودة لا تحصل على صفحة، واللوب الخالي تمامًا من النوتات يُرفض بدلًا من أن يُنسخ فارغًا. ولا يُطبع المقام إلا إذا قُرئ بوضوح.","changelog.0c3d252fc872":"<strong>رزمة من الصفحات.</strong> تخرج الصفحات واحدة تلو الأخرى من المسح الواحد، منشورة كالمروحة على الدرج، ولكل منها عنوان بصيغتها وجزئها (<em>MIDI اللحن</em>، <em>صوت خط الباص</em>) مع <em>الصفحة n/N</em>. انقر صفحة لترفعها إلى الأعلى. <strong>لا يُسحب شيء حتى تستقر الصفحة الأخيرة.</strong>","changelog.55fa665ebb50":"<strong>سحبتان من الرزمة المكتملة.</strong> تحمل الصفحة العليا لسانين باللون الأخضر الليموني: <strong>كل الأجزاء</strong> يسحب كل الصفحات كملفات منفصلة، فيرتّبها الـ DAW مسارًا لكل طبقة؛ و<strong>المزيج الكامل</strong> يسحب ملفًا واحدًا يضم كل شيء — ملف <code>.mid</code> متعدد المسارات لكل الأجزاء، أو التصيير الكامل كملف <code>.wav</code> — يُكتب بجانب الصفحات ولا يُطبع أبدًا. مرّر المؤشر فوق اللسان لترى بيانات المزيج؛ ومن دون مؤشر، يحفظه <em>احفظ المزيج الكامل باسم…</em>.","changelog.7ab067eeb165":"<strong>MIDI ← صوت، جزءًا جزءًا.</strong> يطبع ملف MIDI متعدد الأجزاء صفحة صوت لكل جزء (<em>صوت اللحن</em>، <em>صوت خط الباص</em>)، يُصيَّر كلٌّ منها وحده ويُرسم من ملف WAV الخاص به، إضافةً إلى المزيج الكامل — ومجموع الأجزاء هو المزيج، تحت كسبٍ واحد يحفظ هامش الذروة.","changelog.71cfe75f90c6":"<strong>لوبات حتى 16 مازورة.</strong> يرفض الزجاج المقطع الأطول ذاكرًا طوله بالمازورات، ولا يقصّه أبدًا؛ ولا يزال اللوب ذو المازورة الواحدة أو الاثنتين أو الأربع يُنسخ. وتُعدّ مازورات اللوب الصوتي بالسرعة التي تقرؤه بها آلة النسخ.","changelog.6aed786b024a":"<strong>صفحات صادقة.</strong> تذكر صفحة الأكوردات أنها تتابع، لا التوزيع الذي عُزف؛ وحين يُسمع خط غنائي ويُترك كما هو، تذكر الصفحة الأولى ذلك، واللوب الذي ليس سوى خط غنائي يُرفض مع ذكر ذلك، لا بعبارة «لا شيء للنسخ». كل سرعة مطبوعة تذكر مصدرها — مقروءة من اللوب، أو، حين لا تنطبق ضربات اللوب على أي شبكة، سرعة المضيف أو اسم الملف أو السرعة الافتراضية.","changelog.cb05cd0fc0f0":"<strong><code>flipc</code></strong>، سطر الأوامر، يشغّل زجاج المكوّن الإضافي وآلة نسخه نفسيهما: <code>flipc copy &lt;file&gt; --out &lt;dir&gt;</code>، و<code>flipc facts &lt;file&gt;</code> (كتلة البيانات تمامًا كما تطبعها الورقة)، و<code>flipc score</code> (مقيّم مجموعة الاختبار) و<code>flipc bench</code> (التوقيتات).","changelog.d2365b73e8bc":"<strong>بوابة مجموعة الاختبار.</strong> تُقيَّم مجموعة audioTest في كل تشغيل محلي لـ CI تكون فيه موجودة — وتقول SKIPPED حيث لا تكون — مقابل حدود دنيا لا تتحرك إلا صعودًا.","changelog.d2a673b21c8f":"<strong>تُتابَع سرعة المضيف كتلةً بكتلة</strong>، ويُنسخ ملف MIDI الذي لا سرعة خاصة به بسرعة المضيف لحظةَ ضغطك START.","changelog.ee270218636c":"<strong>سرعة الجلسة لا تحسم إلا التعادل بين الأوكتافات.</strong> لوب بسرعة 120 BPM يُفلَت في جلسة بسرعة 90 BPM يُقرأ على 120 (أربع مازورات)، لا على 90 (ثلاث) — أُصلح ذلك في المستخرِج المشترك لـ MIDI Master، لكل منتج من Freally يقرأ اللوبات.","changelog.ab8ac52d964e":"<strong>مجاني اليوم، دون وعد بأن يبقى كذلك إلى الأبد.</strong> Freally Flipcopy مجاني اليوم، لكنه قد لا يبقى مجانيًا إلى الأبد: قد تُباع الإصدارات المستقبلية. تذكر ذلك الآن كل صفحة من صفحات موقع التوثيق.","changelog.7fb464e21cf8":"<strong>انتقل المستودع</strong> إلى حساب GitHub الخاص بالمشرف نفسه، خاصًا وجميع الحقوق محفوظة، مع حزم Freally المشتركة الآتية من Freally MIDI Master وFreally Oscillate المجاورين؛ وعنوان الإضافة على الويب هو العنوان الجديد لموقع التوثيق.","changelog.c584da8d5dfd":"<strong>يعمل التكامل المستمر على جهاز المشرف</strong> قبل كل عملية دفع — كل البوابات على Windows، وبوابات Linux في Docker Desktop — ولا شيء منه على GitHub Actions. كل إيداع يحمل <code>[skip ci]</code>. (لبضع ساعات في 2026-09-30، كان المستودع عامًّا وكان CI يعمل على GitHub مع كل دفع.)","changelog.79a07e8925af":"<strong>يحتفظ المحرّر بملف تعريف متصفح خاص به.</strong> كانت بيانات WebView2 الخاصة بـ Flipcopy (<code>%APPDATA%\\Freally Flipcopy\\webview</code>) محفوظة ضمن مجلد Freally MIDI Master، ومنتجان يتشاركان ملف تعريف WebView2 واحدًا قد يترك كلٌّ منهما محرّر الآخر فارغًا حين يعملان في الـ DAW نفسه. صار الآن خاصًّا بـ Flipcopy.","changelog.72de476110e3":"<strong>لا يمكن أن يكون المزيج الكامل لنسخةٍ إلا ملفَّها هي</strong>: ملف <code>record.json</code> عُدِّل من وراء آلة النسخ لا يستطيع توجيه سحبٍ أو «حفظ باسم» أو «إظهار النسخة في مجلدها» إلى أي مكان آخر.","changelog.427549a6dab4":"<strong>تُكتب النسخة كاملةً أو لا تُكتب أبدًا.</strong> تكون كل صفحة والمزيج على القرص قبل أن يأخذ أيٌّ منها اسمه، فلا يترك فشلٌ في منتصف الطريق صفحاتٍ في مجلد مرقَّم لا تملكه أي نسخة.","changelog.2604a6288e96":"<strong>لا قصّ في أي صفحة.</strong> يُحدَّد الكسب الواحد لهامش الذروة بناءً على كل ملف تكتبه النسخة — فقد تبلغ ذروة جزءٍ ما أعلى من المزيج حيث تلغيه الأجزاء الأخرى.","changelog.c6cb2c38dd63":"<strong>اللوب ذو الـ 16 مازورة المُصدَّر أطول بـ tick واحدة يبقى 16 مازورة</strong>، لا 17 — فالنوتة الأخيرة التي تُرفع بعد خط المازورة بمقدار 1/32 لا تشكّل مازورة بذاتها.","changelog.2ba628500475":"<strong>تصل رسائل التحكم إلى الصفحة</strong> حتى على قناة لا تعزف أي نوتة.","changelog.833039ba4e85":"<span class=\"release__meta\"><span class=\"release__ver\">v0.2.0</span><time class=\"release__date\" datetime=\"2026-09-30\">2026-09-30</time></span><span class=\"release__title\">آلة النسخ والنسخة الأولى</span>","changelog.35409a92a233":"تقف آلة النسخ على المسرح، وتؤدي مشاهد فيديوهات قصة آلة النسخ المُصيَّرة في Blender بترتيبها: أفلِت ملف MIDI على الزجاج، واضغط START الأخضر، فتخرج نسخة صوتية حقيقية إلى الدرج — مطبوعة من ملفها الخاص، بإطار أخضر ليموني، تسحبها مباشرةً إلى الـ DAW.","changelog.c12f4045ef96":"<strong>آلة النسخ على المسرح.</strong> الآلة مُصيَّرة من مشهد Blender نفسه الذي صُيِّر منه فيديوها القصة — قاعدتها، وغطاؤها كإطارات رسوم متحركة، والمفاتيح المضغوطة، وأقنعة الزجاج والدرج — فوق أرضية النافذة نفسها (<code>#090c09</code>) على فيلم شفاف، فتقف في الغرفة بلا أي حدّ فاصل. المراحل هي مشاهد الفيديوهين بترتيبهما (تنقلب الورقة وتستقر ووجهها إلى الأسفل، وينغلق الغطاء مع ارتداده، وصفارة START، ويمسح المصباح من جانب إلى آخر مسرّبًا ضوءًا سماويًا من الشق الأمامي بينما تخفت الغرفة كلها، وتنزلق النسخة إلى الدرج)، بالمُدد الأقصر للنسخة المختصرة داخل التطبيق؛ ويفشل اختبار إن عرض التطبيق يومًا مشهدًا ليس في القصة، أو تخطّى أحدها، أو عرضها بغير ترتيبها. وتملأ الآلة أي مساحة تمنحها لها النافذة، ولا تنعكس أبدًا في لغة تُكتب من اليمين إلى اليسار.","changelog.81d392181aa1":"<strong>START الأخضر هو المُطلِق الوحيد.</strong> إفلات مقطع لا يفعل سوى وضعه على الزجاج. START (أو <code>Ctrl/Cmd+Enter</code>، الذي يضغط المفتاح نفسه) يبدأ النسخ؛ وSTOP (أو <code>Esc</code>) يلغيه في منتصف المسح دون أن يترك أي أثر؛ وHOME يُفرغ الزجاج. يحمل المفتاح كلمة <em>START</em> مائلة، موجّهة نحو لوحة اللمس، ويضيء مؤشره الضوئي كلما أمكن بدء النسخ. يرسل اختبارٌ للمكوّن الإضافي كل أمر ويفشل إن بدأ أيُّ أمرٍ غير <code>copier_start</code> مهمةً، وتفشل بوابة بناء إن أرسلته الصفحة يومًا من أي مكان غير مفتاح START.","changelog.3c73db8b1385":"<strong>الزجاج.</strong> أفلِت ملف صوت أو MIDI من مستكشف الملفات أو Finder في أي مكان من النافذة (يضيء الزجاج عند وصوله)، أو اضغط <code>Enter</code> على الزجاج الفارغ لاختيار ملف. يُقرأ في خيط معالجة خاص به ويُطبع ووجهه إلى الأعلى قبل أن يستقر — النوتات الحقيقية أو الموجة الصوتية الحقيقية، مع بيانات الملف نفسه. مسارات الشبكة، والملفات الكبيرة جدًا، والطويلة جدًا، والصامتة، والتالفة، وملفات MIDI ذات توقيت SMPTE أو الصيغة 2، يُرفض كلٌّ منها بجملته الخاصة. ملفان في آن واحد: يوضع الأول، وتقول الآلة مقطع واحد في كل مرة. والمقطع الجديد المُفلَت على نسخة منتهية يوضع على الزجاج بالطريقة نفسها، ويُفرَغ الدرج (وتبقى النسخة في مجلد النسخ). والملف الذي يرفضه الزجاج يترك المقطع الذي كان عليه في مكانه.","changelog.4267b3fd96ac":"<strong>MIDI ← صوت.</strong> تُصيِّر النسخة نوتات الملف عبر حبر افتراضي — أصوات MIDI Master الجاهزة للأجزاء النغمية، وآلة إيقاع للطبول بصوت واحد لكل مسار GM — مع احترام ثني الطبقة ودوّاسة الاستدامة (لكل قناة على نوتات تلك القناة فقط)، مع ذيل مدته 2.5 ث، بسرعة الملف (وإلا فبسرعة المضيف — ولا مضيف للتطبيق المستقل — وإلا فبالسرعة الواردة في اسم الملف، وإلا فبـ 120 — وتذكر الصفحة أيّها)، وتبقى تحت −0.3 dBFS، وتُكتب كملف WAV بعمق 24 بت بمعدل عينة المضيف (44.1 kHz في التطبيق المستقل) يضعه الـ DAW على شبكة النبضات. طول النسخة هو أقصى ما يمكن أن تُطبع منه صفحة — خمس دقائق، أو 2:30 فوق 48 kHz — والأطول يُرفض قبل تصييره، ولا يُقصّ أبدًا. يصل «صوت ← MIDI» في <code>v0.3.0</code>؛ وحتى ذلك الحين يقول START ذلك بصدق حين يكون على الزجاج مقطع صوتي.","changelog.d9714ba71fa5":"<strong>مجلد النسخ</strong> (<code>Documents/Freally Flipcopy/Copies</code>): مجلد مرقَّم لكل نسخة، يُحجز ذرّيًا فلا يتشارك اثنان من برامج DAW رقمًا واحدًا أبدًا؛ وصفحات مسمّاة كما يعرضها الـ DAW (<code>Title - Part - 120 BPM, Key.wav</code>)؛ وكل صفحة تُكتب ذرّيًا، وتُقرأ مجددًا ويُتحقَّق منها — و<strong>لا تُنقل ولا تُستبدل ولا تُحذف أبدًا</strong>، لأن الـ DAW يشير إليها بمسارها.","changelog.48b3f94d470b":"<strong>مطبوعات من الملفات نفسها.</strong> كل صفحة — الأصل على الزجاج والنسخة في الدرج — مطبوعة بالليزر مثل مطبوعات فيديوهات القصة: العنوان، وسطر المصدر، ومسطرة المازورات، ولفافة البيانو مع مسار شدة الضغط أو الموجة الصوتية مع <strong>شريط الطيف</strong> الجديد، وكتلة البيانات، وكلها يحسبها المكوّن الإضافي من البايتات الموجودة على القرص. والمازورة ذات الميزان غير المنتظم تحتفظ بنصف نبضتها (يُطبع 7/8 ثلاث نبضات ونصفًا في المازورة). وتذكر صفحة النسخة ما أغفله تصييرها — رسائل التحكم التي لم يعزفها، ونوتات الإيقاع التي لا صوت لها في الطقم — ولا تُسقطها بصمت أبدًا. ويقرأ اختبارٌ بنية صفحات التطبيق ومطبوعات الفيديوهات نفسها ويُلزم كلًّا منهما بالأخرى.","changelog.fa6958b17901":"<strong>اسحب النسخة إلى الـ DAW.</strong> ترتدي الصفحة المُخرَجة إطارًا أخضر ليمونيًا حول مقطعها وتحته <em>اسحب إلى DAW</em> — والإطار هو المقبض. اضغط داخله وحرّك 4 px، فيُسحب ملف النسخة نفسه (مع مطبوعة مصغّرة على المؤشر) إلى FL Studio أو Ableton أو Reaper أو أي DAW يقبل الملفات. لا يُسحب شيء حتى تخرج الصفحة كليًّا؛ وحيث لا يمكن السحب هنا، يصير الإطار رماديًا متقطّعًا ويعرض «حفظ باسم» بدلًا من ذلك. والضغط على <code>Enter</code> فوق الصفحة يفتح «حفظ باسم» أو يُظهر الملف في مجلده.","changelog.4da7005c5000":"<strong>أصوات الآلة</strong>، مُركَّبة من الصفر لآلة النسخ هذه (الوضع، والغطاء، والصفارة، وبدء المسح، وأزيز واحد لكل مسحة مصباح، والإخراج) ويمزجها المكوّن الإضافي في مخرجه نفسه — ولا تكون أبدًا عنصر HTML <code>&lt;audio&gt;</code> — عند −18 dB عبر مستوى Monitor، صامتة أثناء تشغيل الـ DAW (لا تشغيل DAW في التطبيق المستقل لتصمت أثناءه)، وصامتة في التصدير غير الآني، ولا تحلّ أبدًا محل صوت مسارك. وفي الإعدادات تشغيلها وإيقافها، ومستواها، وخيار «صامت أثناء تشغيل DAW».","changelog.f8fc9e0d2e58":"<strong>الشاشة اللمسية</strong> تعرض ما تفعله الآلة، والمقطع الذي تحمله، وكل رفض بلغة المنتِج الموسيقي.","changelog.1a5ee7d7aabc":"<strong>بوابات</strong> لكل ذلك، شوهد كلٌّ منها يفشل قبل الوثوق به: ثلاثي مطابقة الأرضية (ألوان التصيير تساوي رموز التصميم؛ وΔE2000 حول الصورة الظلية لقناة ألفا الخاصة بالآلة في كل مرحلة عند DPR 1 و2؛ ولا شيء يُرسم بين الآلة والأرضية)، وبوابة START (ثابتة، وفي المكوّن الإضافي، وفي Playwright)، وتطابق الطباعة، وبكسلات إطار السحب، ومواصفات مسار التطبيق الجديدة في التطبيق المستقل الحقيقي.","changelog.66b1e687636a":"<strong>الشيفرة المشتركة</strong>: <code>freally-extract</code> (بوابة فك الترميز وتحليل الصوت)، و<code>freally-encode</code> (WAV، وإعادة أخذ العينات، ومقاطع شبكة الـ DAW) و<code>freally-drag</code> (مصدر السحب الأصلي) تُستهلك من MIDI Master عند <code>shared-v5</code>، مع <code>freally_library::audition::NoteRenderer</code>، وأحداث التحكم في <code>read_facts</code>، وخطّاف إفلات الملفات في محوّل عرض الويب، وإعادة وضعه لعرض الويب حين تتحرك النافذة، وشريط عنوانه الفارغ — وكلها أُضيفت هناك في المنبع.","changelog.e7908191194e":"<strong>الأيقونة هي أيقونة المالك نفسه</strong> — حرف <em>F</em> الأخضر الليموني فوق موجة صوتية ولفافة بيانو — على الملف التنفيذي، وحزم المكوّن الإضافي، وأيقونات Linux وmacOS، وموقع التوثيق، بدلًا من الأيقونة المؤقتة.","changelog.719f74499130":"<strong>النافذة.</strong> يحمل شريط عنوان التطبيق المستقل الأيقونة، وهو داكن بلون الغرفة، ولا يقول شيئًا: لا عنوان في شريط عنوان التطبيق المستقل ولا في نافذة المكوّن الإضافي داخل DAW يذكر شريطُ عنوانه اسمَ Flipcopy، لأن الاسم الدوّار أعلى النافذة يقول ذلك أصلًا. وصار ذلك الاسم الدوّار بضعف الحجم ليُقرأ بنظرة، ومتوسّطًا فوق جانب آلة النسخ من النافذة؛ ويمتد متصفح الملفات بجانبه من أعلى النافذة حتى لوحة المعاينة.","changelog.120afa46c010":"يقبل الجسر طلبات حتى 2 MiB (صورة سحب)؛ ويخبر <code>host_info</code> إن كان بالإمكان سحب صفحة هنا.","changelog.df29ffbf7480":"قبل قبول اتفاقية الترخيص، لا تستطيع الصفحة أن تقرأ سوى لغة الواجهة، عبر أمر خاص بها (<code>locale_get</code>)؛ ولا يجيب <code>prefs_get</code> إلا بعد قبولها.","changelog.bf4a28a43b62":"<strong>تحريك النافذة على شاشة مُكبَّرة.</strong> حين يكون Windows مضبوطًا على 150 %، كان سحب نافذة التطبيق المستقل من شريط عنوانها يرسم محتواها متأخرًا عن النافذة بمقدار الثلث، نحو الزاوية العلوية اليسرى للشاشة، فيخفي الحافتين اليمنى والسفلى حتى تُعاد النافذة إلى تلك الزاوية. والآن يبقى المحتوى تمامًا تحت النافذة أينما حُرِّكت.","changelog.f246f03536b6":"<strong>التطبيق المستقل بمقياس شاشتك نفسها.</strong> على شاشة مُكبَّرة (150 %) كان التطبيق المستقل يعمل كبرنامج قديم الطراز غير مُكيَّف للمقياس: كان Windows يمطّ نافذته بينما ترسم الصفحة داخلها بالبكسلات الحقيقية — وهذا أصل أخطاء مواضع السحب والقوائم المنسدلة المذكورة هنا. والآن يُعلن عن نفسه مدركًا لـ DPI كل شاشة قبل أن يفتح نافذة، كما يفعل التطبيقان المستقلان لـ Freally MIDI Master وFreally Unloop، فترسم الصفحة بحدّة بمقياس الشاشة وتُفتح النافذة بحجمها المقصود.","changelog.4d43aa80977a":"<strong>قائمة اللغات تُفتح تحت حقلها.</strong> على شاشة مُكبَّرة كانت القائمة المنسدلة الخاصة بالنظام تُفتح أسفل حقل الإعدادات وإلى يمينه، وتبتعد أكثر كلما ابتعد الحقل عن زاوية النافذة؛ والآن يرسم Flipcopy القائمة بنفسه، تحت الحقل مباشرةً، بأسلوب النافذة الداكن نفسه، مع كتابة كل لغة بخطّها الخاص.","changelog.a348e37f07eb":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-09-26\">2026-09-26</time></span><span class=\"release__title\">الأساس والعمود الفقري لـ CI</span>","changelog.8847996db9e9":"المنتج الفارغ الذي تُبنى عليه كل درجة لاحقة: يُحمَّل، ويمرّر الصوت دون أن يمسّه، ويطلب قبول اتفاقية الترخيص، ويفتح نافذته الداكنة، وتعمل كل بوابات الجودة.","changelog.cc29ebe17a90":"<strong>المكوّن الإضافي، بكل الصيغ من ملف ثنائي واحد.</strong> مكوّن CLAP إضافي مبني بـ nih-plug، مع نقاط دخول VST3 وAUv2 يُسقطها <code>clap-wrapper</code> (نظيف الترخيص: لا روابط VST3 بترخيص GPL)، إضافةً إلى <strong>التطبيق المستقل</strong> — تطبيق سطح مكتب أصلي بنافذته وجهاز صوته الخاصين، وليس تطبيق ويب أبدًا. دخل وخرج ستيريو، ومدخل نوتات لميزة «المسح من مسار» اللاحقة، وزمن تأخير صفري، ويمرّ صوت المسار <strong>بتًّا ببت</strong> (يثبت ذلك اختبار الإلغاء). مفتاح <strong>Bypass</strong> للمضيف ومستوى <strong>Monitor</strong> للصوت الذي سيضيفه Flipcopy نفسه (أصوات الآلة والمعاينة، بدءًا من <code>v0.2.0</code>) — ولا يمسّ المسار أبدًا. حالة محفوظة ذات إصدار، محدودة الحجم، تُرحَّل، وتُرفض ككل بدلًا من تحميلها نصفيًا، فلا يتسبب مشروع تالف أبدًا في انهيار المضيف.","changelog.59616adfaedb":"<strong>اتفاقية الترخيص</strong> (<code>EULA.md</code>، ببنية مثل اتفاقية Freally Oscillate) وبوابتها: يطلب منك Flipcopy قبولها عند أول فتح ويبقى خاملًا حتى تفعل — لا يقرأ شيئًا، ولا ينسخ شيئًا، ولا يضيف شيئًا إلى مسارك. الاتفاقية مُضمَّنة في المكوّن الإضافي عند بنائه وتُقدَّم منه، وينتظر زر موافق حتى يُقرأ النص إلى نهايته، وتتشارك إجابتك كل نسخة مفتوحة والتطبيق المستقل. والرفض الذي تعذّر حفظه يقول ذلك.","changelog.ed5631790156":"<strong>النافذة</strong>، تُفتح بحجم 1400 × 875 (حجم Freally Unloop) وتتحجّم ككتلة واحدة إلى أي حجم — كل شيء يحافظ على تناسبه، بلا أي شريط حوله — تحت شريط عنوان يدور فيه <em>Freally Flipcopy</em> وإصداره حول المحور Y بثلاثة أبعاد، تمامًا كما في Freally Oscillate وFreally MIDI Master (ويثبتان حين تُقلَّل الحركة): الهيكل الداكن مع شريط المتصفح ولوحة المعاينة في جهة بداية السطر، وفاصل قابل للسحب (260–420 px، وبمفاتيح الأسهم أيضًا)، والمسرح — الذي لا خلفية خاصة به، كي تقف آلة النسخ في الغرفة بلا أي حدّ فاصل حولها. سمة واحدة، داكنة، ولا شيء يمكن أن يصنع سمة ثانية.","changelog.ccf91016802f":"<strong>ثماني عشرة لغة</strong> لكل ما في النافذة، مع حفظ الاختيار لكل جهاز ومشاركته بين كل النسخ المفتوحة؛ وتخطيطات من اليمين إلى اليسار للعربية.","changelog.92d766745704":"<strong>خطوط Noto من Google</strong>، مُضمَّنة في الحزمة بموجب SIL Open Font License 1.1، ويُرفق الترخيص بجانبها.","changelog.b502e66ba7a3":"<strong>موقع التوثيق</strong>، مبني مثل موقع Freally Oscillate وداكن فقط، باللغات الثماني عشرة نفسها (تُحمَّل كل منها فقط حين يختارها القارئ): الصفحة الرئيسية مع سلّم الإصدارات (مُولَّد من <code>docs/ladder.json</code> وتُلزمه بوابةٌ بالخطة الخاصة)، وقصتا آلة النسخ المُصيَّرتان في Blender ضمن «شاهدها وهي تنسخ»، والتوثيق، وسجل التغييرات هذا، وصفحة تنزيل تقول بوضوح إنه لا شيء للتنزيل قبل <code>v1.0.0</code>. تُعرض القصتان بصوتهما، فقط حين تضغط START المائل على مفتاح آلة النسخ الأخضر (أو زر التشغيل)، وتستقران على إطارهما الأول حين تنتهيان أو تُوقَفان؛ وتطبع قصة صوت ← MIDI صفحة لكل طبقة — MIDI اللحن، وMIDI الأكوردات، وMIDI خط الباص، وMIDI اللحن المضاد — واحدة تلو الأخرى على رزمة في الدرج، كلٌّ منها بإطار أخضر ليموني وتحته <em>اسحب إلى DAW</em>.","changelog.96a59e69b7f8":"<strong>يبقى النص داخل حاوياته</strong> في اللغات الـ 18 كلها، في النافذة الافتراضية وفي أصغر نافذة (فحص Playwright على كل تسمية).","changelog.495bcdf8956e":"<strong>البوابات</strong>، شوهد كلٌّ منها يفشل قبل الوثوق به: التنسيق، وclippy، وكل الاختبارات، وفحوص الأنواع، والتدقيق الأسلوبي، وبوابة اللغات (18 كتالوجًا، بمفاتيح وعناصر نائبة متطابقة، ومترجمة فعلًا)، وتدقيق CSS المنطقي، ورموز التصميم والتباين، والوضع الداكن فقط، وقائمة الحظر (لا ذكاء اصطناعي، لا شبكة، لا قياس عن بُعد)، وتدقيق التراخيص، وبوابة الحزم المشتركة (استهلاك لا تفرّع)، وأسماء المنتجات (لا علامة تجارية لصانع آلات نسخ أبدًا)، وانجراف ملفات الربط، والسلّم، ولا تنزيلات قبل 1.0، وميزانية الأصول، و<code>clap-validator</code> و<code>pluginval</code> بدرجة صرامة 10، وCI محلي على Windows وفي Docker لـ Linux، وPlaywright على مسارين — المتصفح ونافذة التطبيق المستقل الحقيقية.","changelog.8f6fb4eb7f42":"الأمان","changelog.09dd8d0ea4e1":"لا يحمّل المحرّر إلا الصفحة المُضمَّنة في الملف الثنائي، تحت سياسة أمان محتوى صارمة؛ ولا يجيب جسره إلا على طلب JSON <code>POST</code> الصادر من الصفحة نفسها، ويرفض أي شيء يتجاوز 64 KiB وأي مسار يحوي <code>..</code>، وقبل قبول الاتفاقية لا يجيب إلا على قائمة مسموح بها من الأوامر. ولا تفتح بُنى الإصدار أدوات DevTools ولا منفذ تصحيح عن بُعد.","changelog.e06fbd4d3359":"لا شيفرة شبكة في المكوّن الإضافي ولا في التطبيق المستقل، ويتحقق من ذلك المُصرِّف (<code>clippy.toml</code>) ومخطط الاعتماديات (<code>scripts/check-denylist.mjs</code>).","changelog.70e17daefb45":"الملفات التي يحتفظ بها Flipcopy في مجلد بيانات التطبيقات لديك (إجابة الاتفاقية والتفضيلات) تُقرأ بحدٍّ للحجم وتُكتب ذرّيًا، فيُحمَّل الملف التالف أو المُعدَّل يدويًا كقيم افتراضية، ولا يترك أي انهيار نصف ملف أبدًا."};
